import test from 'node:test';
import assert from 'node:assert/strict';
import { 
  calculateIndividualHealCost, 
  pokemonNeedsHealing, 
  calculateTotalHealCost,
  HEAL_COST_TIER_MULTIPLIERS
} from '../../src/logic/economy/economyFormulas.ts';
import type { Pokemon } from '../../src/types/pokemon';

test('Economy Formulas: pokemonNeedsHealing', () => {
  const healthyPkmn: Partial<Pokemon> = {
    hp: 100,
    maxHp: 100,
    status: null,
    moves: [{ name: 'Tackle', pp: 20, maxPP: 20 }] as any
  };

  const damagedPkmn: Partial<Pokemon> = {
    hp: 90,
    maxHp: 100,
    status: null,
    moves: []
  };

  const statusPkmn: Partial<Pokemon> = {
    hp: 100,
    maxHp: 100,
    status: 'poison',
    moves: []
  };

  const ppPkmn: Partial<Pokemon> = {
    hp: 100,
    maxHp: 100,
    status: null,
    moves: [{ name: 'Tackle', pp: 10, maxPP: 20 }] as any
  };

  assert.strictEqual(pokemonNeedsHealing(healthyPkmn as Pokemon), false, 'Healthy pokemon should not need healing');
  assert.strictEqual(pokemonNeedsHealing(damagedPkmn as Pokemon), true, 'Damaged pokemon should need healing');
  assert.strictEqual(pokemonNeedsHealing(statusPkmn as Pokemon), true, 'Pokemon with status should need healing');
  assert.strictEqual(pokemonNeedsHealing(ppPkmn as Pokemon), true, 'Pokemon with low PP should need healing');
});

test('Economy Formulas: calculateIndividualHealCost', () => {
  const pkmn: Partial<Pokemon> = {
    id: 'bulbasaur',
    ivs: { hp: 0, atk: 0, def: 0, spa: 0, spd: 0, spe: 0 }
  };

  // For non-rocket, cost is always 0
  assert.strictEqual(calculateIndividualHealCost(pkmn as Pokemon, 10, 'trainer'), 0);

  // For rocket, level 10, tier F (multiplier 1)
  // basePrice = 20 + (10 * 3) = 50
  assert.strictEqual(calculateIndividualHealCost(pkmn as Pokemon, 10, 'rocket'), 50);

  // For rocket, level 10, tier S+ (multiplier 10)
  // Let's mock a high IV pokemon
  const highTierPkmn: Partial<Pokemon> = {
    id: 'bulbasaur',
    ivs: { hp: 31, atk: 31, def: 31, spa: 31, spd: 31, spe: 31 }
  };
  // basePrice 50 * 10 = 500
  assert.strictEqual(calculateIndividualHealCost(highTierPkmn as Pokemon, 10, 'rocket'), 500);
});

test('Economy Formulas: calculateTotalHealCost', () => {
  const p1: Partial<Pokemon> = { hp: 100, maxHp: 100, ivs: { hp: 0, atk: 0, def: 0, spa: 0, spd: 0, spe: 0 } }; // Healthy
  const p2: Partial<Pokemon> = { hp: 50, maxHp: 100, ivs: { hp: 0, atk: 0, def: 0, spa: 0, spd: 0, spe: 0 } }; // Needs healing

  const team = [p1 as Pokemon, p2 as Pokemon, null];

  // For trainer, cost 0
  assert.strictEqual(calculateTotalHealCost(team, 10, 'trainer'), 0);

  // For rocket, only p2 counts
  // cost = 50
  assert.strictEqual(calculateTotalHealCost(team, 10, 'rocket'), 50);
});

import test from 'node:test';
import assert from 'node:assert/strict';
import { 
  applyMarketFilters, 
  buildMarketSaleLabel, 
  ensureMarketSoldSeenState 
} from '../../src/logic/market.ts';
import type { MarketListing, MarketFilters } from '../../src/logic/market.ts';
import type { GameState } from '../../src/types/game';

const mockListing: MarketListing = {
  id: 'uuid-1',
  listing_type: 'pokemon',
  price: 1000,
  seller_id: 'seller-1',
  created_at: '2026-05-13T10:00:00Z',
  status: 'active',
  data: {
    name: 'Pikachu',
    level: 10,
    type: 'electric',
    ivs: { hp: 10, atk: 10, def: 10, spa: 10, spd: 10, spe: 10 }
  }
};

const defaultFilters: MarketFilters = {
  mode: 'pokemon',
  search: '',
  priceMin: 0,
  priceMax: 10000,
  tier: 'all',
  type: 'all',
  levelMin: 1,
  levelMax: 100,
  ivTotalMin: 0,
  ivTotalMax: 186,
  ivAny31: false,
  itemCat: 'all'
};

test('Market Logic: applyMarketFilters', () => {
  const list = [mockListing];

  // Match all
  assert.strictEqual(applyMarketFilters(list, defaultFilters, 'explore').length, 1);

  // Filter by search
  assert.strictEqual(applyMarketFilters(list, { ...defaultFilters, search: 'Pika' }, 'explore').length, 1);
  assert.strictEqual(applyMarketFilters(list, { ...defaultFilters, search: 'Charm' }, 'explore').length, 0);

  // Filter by price
  assert.strictEqual(applyMarketFilters(list, { ...defaultFilters, priceMax: 500 }, 'explore').length, 0);

  // Filter by type
  assert.strictEqual(applyMarketFilters(list, { ...defaultFilters, type: 'electric' }, 'explore').length, 1);
  assert.strictEqual(applyMarketFilters(list, { ...defaultFilters, type: 'fire' }, 'explore').length, 0);
});

test('Market Logic: buildMarketSaleLabel', () => {
  assert.strictEqual(buildMarketSaleLabel(mockListing), 'tu Pokémon Pikachu');

  const itemListing: MarketListing = {
    ...mockListing,
    listing_type: 'item',
    data: { name: 'Poke Ball', qty: 5 }
  };
  assert.strictEqual(buildMarketSaleLabel(itemListing), 'tu objeto Poke Ball x5');
});

test('Market Logic: state management (seen ids)', () => {
  const state = { marketSoldSeenIds: [] } as unknown as GameState;

  const result = ensureMarketSoldSeenState(state);
  assert.deepStrictEqual(result, []);

  state.marketSoldSeenIds = ['valid-id', '', '  ', 123 as any];
  const cleaned = ensureMarketSoldSeenState(state);
  assert.deepStrictEqual(cleaned, ['valid-id']);
});

import { describe, it, expect, beforeEach, vi } from 'vitest';
import { setActivePinia, createPinia } from 'pinia';
import { useGTSStore } from '../../src/stores/gts';
import { useGameStore } from '../../src/stores/game';
import { useUIStore } from '../../src/stores/ui';

describe('GTS Store', () => {
  beforeEach(() => {
    setActivePinia(createPinia());
    const ui = useUIStore();
    ui.notify = vi.fn();
    ui.setLoading = vi.fn();
  });

  it('handles cancellation successfully', async () => {
    const gts = useGTSStore();
    const game = useGameStore();
    const ui = useUIStore();

    // Mock RPC
    game.db.rpc = vi.fn().mockResolvedValue({ data: true, error: null });
    game.fetchClaimQueue = vi.fn().mockResolvedValue([]);

    // We need to mock fetchUserData to avoid actual DB calls
    // Since fetchUserData is private or internal, we can't easily mock it unless we exported it.
    // However, we can mock the entire game.db.from chain if needed.

    const result = await gts.cancelListing('123');

    expect(result).toBe(true);
    expect(ui.setLoading).toHaveBeenCalledWith(true);
    expect(ui.setLoading).toHaveBeenCalledWith(false);
    expect(ui.notify).toHaveBeenCalledWith(expect.stringContaining('Publicación cancelada'), '✅');
  });

  it('handles cancellation errors', async () => {
    const gts = useGTSStore();
    const game = useGameStore();
    const ui = useUIStore();

    game.db.rpc = vi.fn().mockResolvedValue({ data: null, error: { message: 'Not authorized' } });

    const result = await gts.cancelListing('123');

    expect(result).toBe(false);
    expect(ui.notify).toHaveBeenCalledWith('Not authorized', '❌');
  });

  it('handles buying a listing successfully', async () => {
    const gts = useGTSStore();
    const game = useGameStore();
    const ui = useUIStore();

    const mockListing = { id: 'list-1', price: 100, listing_type: 'item', data: { name: 'Potion' } };
    game.state.money = 500;
    game.db.rpc = vi.fn().mockResolvedValue({ data: { money: 400 }, error: null });
    game.fetchClaimQueue = vi.fn().mockResolvedValue([]);

    const result = await gts.buyListing(mockListing as any);

    expect(result).toBe(true);
    expect(ui.setLoading).toHaveBeenCalledWith(true);
    expect(ui.notify).toHaveBeenCalledWith(expect.stringContaining('Compra exitosa'), '✅');
  });
});

import { describe, it, expect, beforeEach, vi } from 'vitest';
import { setActivePinia, createPinia } from 'pinia';
import { useShopStore } from '../../src/stores/shop';
import { useGameStore } from '../../src/stores/game';
import { useUIStore } from '../../src/stores/ui';
import { SHOP_ITEMS } from '../../src/data/items';

describe('Shop Store', () => {
  beforeEach(() => {
    setActivePinia(createPinia());
    // Mock UI notify
    const ui = useUIStore();
    ui.notify = vi.fn();
  });

  it('calculates quantities correctly', () => {
    const shop = useShopStore();
    expect(shop.getQuantity('pokeball')).toBe(1);

    shop.setQuantity('pokeball', 5);
    expect(shop.getQuantity('pokeball')).toBe(5);

    shop.setQuantity('pokeball', -1);
    expect(shop.getQuantity('pokeball')).toBe(1);

    shop.setQuantity('pokeball', 1000);
    expect(shop.getQuantity('pokeball')).toBe(999);
  });

  it('allows buying items with enough money', () => {
    const shop = useShopStore();
    const game = useGameStore();
    const ui = useUIStore();

    game.state.money = 1000;
    game.state.trainerLevel = 10;
    game.state.inventory = {};

    const item = SHOP_ITEMS.find(i => i.id === 'pokeball')!;
    const price = item.price;

    shop.setQuantity('pokeball', 2);
    shop.buyItem('pokeball');

    expect(game.state.money).toBe(1000 - (price * 2));
    expect(game.state.inventory[item.name]).toBe(2);
    expect(ui.notify).toHaveBeenCalledWith(expect.stringContaining('Compraste x2'), item.icon);
  });

  it('prevents buying items without enough money', () => {
    const shop = useShopStore();
    const game = useGameStore();
    const ui = useUIStore();

    game.state.money = 10;
    game.state.trainerLevel = 1;
    shop.buyItem('pokeball');

    expect(game.state.money).toBe(10); // No change
    expect(ui.notify).toHaveBeenCalledWith(expect.stringContaining('No tenés suficiente dinero'), '💸');
  });

  it('allows buying items with Battle Coins', () => {
    const shop = useShopStore();
    const game = useGameStore();

    game.state.battleCoins = 5000;
    game.state.trainerLevel = 30; // High enough for anything
    game.state.inventory = {};

    // Destiny Knot costs 4800 BC
    const item = SHOP_ITEMS.find(i => i.id === 'destiny_knot')!;

    shop.buyItemBC(item.id);

    expect(game.state.battleCoins).toBe(5000 - 4800);
    expect(game.state.inventory[item.name]).toBe(1);
  });

  it('restores HP and PP when healing all pokemon', () => {
    const shop = useShopStore();
    const game = useGameStore();

    game.state.money = 1000;
    game.state.playerClass = 'trainer'; // Free healing for non-rocket
    game.state.team = [{
      hp: 10,
      maxHp: 100,
      status: 'poison',
      moves: [{ pp: 5, maxPP: 20 }]
    }] as any;

    const success = shop.healAllPokemon();

    expect(success).toBe(true);
    expect(game.state.team[0].hp).toBe(100);
    expect(game.state.team[0].status).toBe(null);
    expect(game.state.team[0].moves[0].pp).toBe(20);
  });
});
